import { ref, computed } from "vue";
import { useI18n } from "vue-i18n";
import * as z from "zod";
import type { ProviderPayload } from "@/api/client";
import type { Provider, ModelInfo } from "@/types/mapping";
import { DEFAULT_CONTEXT_WINDOW, DEFAULT_STREAM_TIMEOUT_MS } from "@/constants";
import type { ModelConfig } from "@/components/quick-setup/types";
import { useTransformRules } from "@/composables/useTransformRules";
import { useProviderPresets } from "@/composables/useProviderPresets";
import type { ConcurrencyMode } from "@/types/concurrency";

const DEFAULT_CONCURRENCY = 3;
const DEFAULT_CONCURRENCY_AUTO = 10;
const DEFAULT_QUEUE_TIMEOUT_MS = 120_000;
const DEFAULT_QUEUE_SIZE = 10;
const MAX_CONCURRENCY = 100;
const MAX_QUEUE_SIZE = 1000;
const CONTEXT_K = 1000;
const CONTEXT_M = 1_000_000;
const MS_PER_SECOND = 1000;

interface FormState {
  name: string;
  api_type: string;
  base_url: string;
  upstream_path: string;
  api_key: string;
  models: ModelInfo[];
  is_active: boolean;
  max_concurrency: number;
  queue_timeout_ms: number;
  max_queue_size: number;
  adaptive_enabled: boolean;
  proxy_type: string;
  proxy_url: string;
  proxy_username: string;
  proxy_password: string;
}

const DEFAULT_FORM: FormState = {
  name: "",
  api_type: "anthropic",
  base_url: "",
  upstream_path: "",
  api_key: "",
  models: [],
  is_active: true,
  max_concurrency: DEFAULT_CONCURRENCY_AUTO,
  queue_timeout_ms: DEFAULT_QUEUE_TIMEOUT_MS,
  max_queue_size: DEFAULT_QUEUE_SIZE,
  adaptive_enabled: true,
  proxy_type: "",
  proxy_url: "",
  proxy_username: "",
  proxy_password: "",
};

const CONTEXT_WINDOW_OPTIONS = [
  { label: "8K", value: "8000" },
  { label: "16K", value: "16000" },
  { label: "32K", value: "32000" },
  { label: "64K", value: "64000" },
  { label: "128K", value: "128000" },
  { label: "160K", value: "160000" },
  { label: "200K", value: "200000" },
  { label: "256K", value: "256000" },
  { label: "1M", value: "1000000" },
] as const;

export const API_TYPE_LABELS: Record<string, string> = {
  openai: "OpenAI Chat Completions",
  "openai-responses": "OpenAI Responses",
  anthropic: "Anthropic Messages",
};

export { CONTEXT_WINDOW_OPTIONS, MS_PER_SECOND, CONTEXT_K, CONTEXT_M };

type ProviderFormPayload = Pick<
  ProviderPayload,
  | "name"
  | "api_type"
  | "base_url"
  | "upstream_path"
  | "models"
  | "is_active"
  | "max_concurrency"
  | "queue_timeout_ms"
  | "max_queue_size"
  | "adaptive_enabled"
  | "proxy_type"
  | "proxy_url"
  | "proxy_username"
  | "proxy_password"
> & { api_key?: string };

export function useProviderForm() {
  const { t } = useI18n();
  const { transformForm, loadTransformRules, saveTransformRules } =
    useTransformRules();

  const form = ref<FormState>({ ...DEFAULT_FORM });
  const errors = ref<Record<string, string>>({});
  const concurrencyMode = ref<ConcurrencyMode>("auto");
  const dialogOpen = ref(false);
  const editingId = ref<string | null>(null);
  const modelInput = ref("");
  const modelContextWindow = ref(DEFAULT_CONTEXT_WINDOW);
  const contextWindowSelect = computed({
    get: () => `${modelContextWindow.value}`,
    set: (val: string) => {
      modelContextWindow.value = Number(val);
    },
  });

  const presetHook = useProviderPresets(form);

  function validate(): boolean {
    const schema = z.object({
      name: z
        .string()
        .min(1, t("providers.validation.nameRequired"))
        .regex(/^[a-zA-Z0-9_-]+$/, t("providers.validation.namePattern")),
      base_url: z
        .string()
        .min(1, t("providers.validation.baseUrlRequired"))
        .url(t("providers.validation.baseUrlInvalid")),
    });
    const errs: Record<string, string> = {};
    const result = schema.safeParse({
      name: form.value.name.trim(),
      base_url: form.value.base_url.trim(),
    });
    if (!result.success) {
      for (const issue of result.error.issues) {
        const field = issue.path[0] as string;
        if (!errs[field]) errs[field] = issue.message;
      }
    }
    if (!editingId.value && !form.value.api_key.trim())
      errs.api_key = t("providers.validation.apiKeyRequired");
    if (concurrencyMode.value !== "none") {
      const mc = form.value.max_concurrency;
      if (!mc || mc < 1 || mc > MAX_CONCURRENCY)
        errs.max_concurrency = t("providers.validation.concurrencyRange", {
          min: 1,
          max: MAX_CONCURRENCY,
        });
      if (form.value.queue_timeout_ms < 0)
        errs.queue_timeout_ms = t("providers.validation.negativeNotAllowed");
      const qs = form.value.max_queue_size;
      if (!qs || qs < 1 || qs > MAX_QUEUE_SIZE)
        errs.max_queue_size = t("providers.validation.queueSizeRange", {
          min: 1,
          max: MAX_QUEUE_SIZE,
        });
    }
    errors.value = errs;
    return Object.keys(errs).length === 0;
  }

  function buildPayload(): ProviderFormPayload {
    const payload: ProviderFormPayload = {
      name: form.value.name,
      api_type: form.value.api_type,
      base_url: form.value.base_url,
      upstream_path: form.value.upstream_path || undefined,
      models: form.value.models.map((m) => ({
        name: m.name,
        context_window: m.context_window ?? undefined,
        patches: m.patches ?? undefined,
        stream_timeout_ms: m.stream_timeout_ms ?? undefined,
        capabilities: m.capabilities ?? undefined,
      })),
      is_active: form.value.is_active ? 1 : 0,
      max_concurrency:
        concurrencyMode.value === "none" ? 0 : form.value.max_concurrency,
      queue_timeout_ms:
        concurrencyMode.value === "none" ? 0 : form.value.queue_timeout_ms,
      max_queue_size:
        concurrencyMode.value === "none"
          ? DEFAULT_QUEUE_SIZE
          : form.value.max_queue_size,
      adaptive_enabled: concurrencyMode.value === "auto" ? 1 : 0,
      proxy_type: form.value.proxy_type || null,
      proxy_url: form.value.proxy_url?.trim() || null,
      proxy_username: form.value.proxy_username?.trim() || null,
      proxy_password: form.value.proxy_password || null,
    };
    if (form.value.api_key) payload.api_key = form.value.api_key;
    return payload;
  }

  function addModel() {
    const input = modelInput.value.trim();
    if (!input) return;
    const names = input
      .split(/[,，]/)
      .map((s) => s.trim())
      .filter(Boolean);
    for (const name of names) {
      if (!form.value.models.some((m) => m.name === name)) {
        form.value.models.push({
          name,
          context_window: modelContextWindow.value || DEFAULT_CONTEXT_WINDOW,
          patches: [],
          stream_timeout_ms: DEFAULT_STREAM_TIMEOUT_MS,
          capabilities: ["text"],
        });
      }
    }
    modelInput.value = "";
    modelContextWindow.value = DEFAULT_CONTEXT_WINDOW;
  }

  function removeModel(index: number) {
    form.value.models.splice(index, 1);
  }

  function updateModel(index: number, updated: ModelConfig) {
    form.value.models[index].context_window = updated.contextWindow;
    form.value.models[index].patches = updated.patches;
  }

  /** 切换模型的指定能力。text 为基础能力，不可关闭。 */
  function toggleModelCapability(index: number, capability: string) {
    if (capability === "text") return;
    const model = form.value.models[index];
    const caps = model.capabilities ?? ["text"];
    const hasIt = caps.includes(capability);
    model.capabilities = hasIt
      ? caps.filter((c) => c !== capability)
      : [...caps, capability];
  }

  function updateModelTimeout(index: number, seconds: string | number) {
    const val = Number(seconds);
    form.value.models[index].stream_timeout_ms =
      val > 0 ? val * MS_PER_SECOND : null;
  }

  function onConcurrencyModeChange(mode: ConcurrencyMode) {
    concurrencyMode.value = mode;
    if (mode === "auto") {
      if (!form.value.max_concurrency || form.value.max_concurrency < 1)
        form.value.max_concurrency = DEFAULT_CONCURRENCY_AUTO;
      form.value.adaptive_enabled = true;
    } else if (mode === "manual") {
      if (!form.value.max_concurrency || form.value.max_concurrency < 1)
        form.value.max_concurrency = DEFAULT_CONCURRENCY;
      form.value.adaptive_enabled = false;
    }
  }

  function isOfficialOpenai(url: string): boolean {
    return url.includes("api.openai.com");
  }

  function openCreate() {
    editingId.value = null;
    form.value = { ...DEFAULT_FORM, models: [] };
    concurrencyMode.value = "auto";
    modelInput.value = "";
    modelContextWindow.value = DEFAULT_CONTEXT_WINDOW;
    presetHook.presetGroup.value = "";
    presetHook.presetPlan.value = "";
    errors.value = {};
    dialogOpen.value = true;
  }

  function openEdit(p: Provider) {
    editingId.value = p.id;
    const mc = p.max_concurrency ?? 0;
    if (mc === 0) concurrencyMode.value = "none";
    else if (p.adaptive_enabled) concurrencyMode.value = "auto";
    else concurrencyMode.value = "manual";
    form.value = {
      name: p.name,
      api_type: p.api_type,
      base_url: p.base_url,
      upstream_path: p.upstream_path || "",
      api_key: "",
      models: (p.models || []).map((m) => ({
        name: m.name,
        context_window: m.context_window ?? DEFAULT_CONTEXT_WINDOW,
        patches: m.patches ?? [],
        stream_timeout_ms: m.stream_timeout_ms ?? null,
        capabilities: m.capabilities ?? ["text"],
      })),
      is_active: !!p.is_active,
      max_concurrency:
        concurrencyMode.value === "none" ? DEFAULT_CONCURRENCY_AUTO : mc,
      queue_timeout_ms: p.queue_timeout_ms ?? DEFAULT_QUEUE_TIMEOUT_MS,
      max_queue_size: p.max_queue_size ?? DEFAULT_QUEUE_SIZE,
      adaptive_enabled: concurrencyMode.value === "auto",
      proxy_type: p.proxy_type || "",
      proxy_url: p.proxy_url || "",
      proxy_username: p.proxy_username || "",
      proxy_password: "",
    };
    presetHook.presetGroup.value = "";
    presetHook.presetPlan.value = "";
    modelInput.value = "";
    modelContextWindow.value = DEFAULT_CONTEXT_WINDOW;
    errors.value = {};
    dialogOpen.value = true;
    loadTransformRules(p.id);
  }

  return {
    form,
    errors,
    concurrencyMode,
    dialogOpen,
    editingId,
    modelInput,
    modelContextWindow,
    contextWindowSelect,
    transformForm,
    presetHook,
    validate,
    buildPayload,
    addModel,
    removeModel,
    updateModel,
    updateModelTimeout,
    toggleModelCapability,
    onConcurrencyModeChange,
    isOfficialOpenai,
    openCreate,
    openEdit,
    saveTransformRules,
  };
}

import {
  ref,
  computed,
  onMounted,
  watch,
  type Ref,
  type ComputedRef,
} from "vue";
import { useI18n } from "vue-i18n";
import {
  api,
  getApiMessage,
  type ProviderGroup,
  type RecommendedRetryRule,
  type QuickSetupPayload,
} from "@/api/client";
import type { MappingGroup } from "@/types/mapping";
import type { Provider as ApiProvider } from "@/types/mapping";
import { toast } from "vue-sonner";
import {
  type ClientType,
  type ModelConfig,
  type MappingEntry,
  type MappingTarget,
  CLIENTS,
  DEFAULT_CLIENT_MAPPINGS,
  getDefaultContextWindow,
} from "@/components/quick-setup/types";
import { DEFAULT_CONTEXT_WINDOW, DEFAULT_STREAM_TIMEOUT_MS } from "@/constants";
import type { Rule } from "@/types/mapping";
import type { ConcurrencyMode } from "@/types/concurrency";
import { computeDefaultPatches } from "@/utils/model-patches";
import router from "@/router";

const DEFAULT_CONCURRENCY = 10;
const DEFAULT_QUEUE_TIMEOUT_MS = 120_000;
const DEFAULT_QUEUE_SIZE = 100;
const CONNECTION_TEST_DELAY_MS = 800;
const POST_SAVE_REDIRECT_MS = 1500;

/** Convert Chinese provider group name to valid backend name (a-zA-Z0-9_-) */
const PROVIDER_NAME_MAP: Record<string, string> = {
  DeepSeek: "deepseek",
  百度千帆: "qianfan",
  科大讯飞: "iflytek",
  硅基流动: "siliconflow",
  智谱: "zhipu",
  月之暗面: "moonshot",
  Minimax: "minimax",
  火山引擎: "volcengine",
  阿里云: "aliyun",
  腾讯云: "tencent",
  OpenCode: "opencode",
  阶跃星辰: "stepfun",
};

function toProviderName(group: string): string {
  return (
    PROVIDER_NAME_MAP[group] ??
    group
      .toLowerCase()
      .replace(/[^a-z0-9]/gi, "-")
      .replace(/-+/g, "-")
  );
}

function parseTransformRules(
  headersInput: string,
  dropFieldsInput: string,
  requestDefaultsInput: string,
  onError: (msg: string) => void,
): NonNullable<QuickSetupPayload["transform_rules"]> | undefined | false {
  if (!headersInput && !dropFieldsInput && !requestDefaultsInput)
    return undefined;
  const result: NonNullable<QuickSetupPayload["transform_rules"]> = {};
  if (headersInput) {
    try {
      result.inject_headers = JSON.parse(headersInput);
    } catch {
      onError("injectHeadersJsonError");
      return false;
    }
  }
  if (dropFieldsInput) {
    result.drop_fields = dropFieldsInput
      .split(",")
      .map((s) => s.trim())
      .filter(Boolean);
  }
  if (requestDefaultsInput) {
    try {
      result.request_defaults = JSON.parse(requestDefaultsInput);
    } catch {
      onError("requestDefaultsJsonError");
      return false;
    }
  }
  return Object.keys(result).length > 0 ? result : undefined;
}

/** Toggle active state for existing mappings that changed */
async function toggleChangedMappings(
  entries: MappingEntry[],
): Promise<string[]> {
  const errors: string[] = [];
  for (const entry of entries) {
    if (
      entry.existing &&
      entry.existingId &&
      entry.originalActive !== undefined &&
      entry.active !== entry.originalActive
    ) {
      try {
        await api.toggleMappingGroup(entry.existingId);
      } catch {
        errors.push(entry.clientModel);
      }
    }
  }
  return errors;
}

/** Build retry rules payload from selected rules */
function buildRetryRulesPayload(
  rules: RecommendedRetryRule[],
  selectedRules: Set<string>,
): QuickSetupPayload["retry_rules"] {
  return rules
    .filter((r) => selectedRules.has(r.name) && !r.exists)
    .map((r) => ({
      name: r.name,
      status_code: r.status_code,
      body_pattern: r.body_pattern,
      retry_strategy: r.retry_strategy,
      retry_delay_ms: r.retry_delay_ms,
      max_retries: r.max_retries,
      max_delay_ms: r.max_delay_ms,
    }));
}

interface ProviderPayloadInput {
  isCustom: boolean;
  selectedGroup: string;
  selectedPlan: string;
  apiType: "openai" | "openai-responses" | "anthropic";
  baseUrl: string;
  upstreamPath: string;
  apiKey: string;
  models: ModelConfig[];
  concurrencyMode: ConcurrencyMode;
  maxConcurrency: number;
  queueTimeoutMs: number;
  maxQueueSize: number;
}

function buildProviderPayload(
  input: ProviderPayloadInput,
): QuickSetupPayload["provider"] {
  return {
    name: input.isCustom
      ? `custom-${Date.now()}`
      : `${toProviderName(input.selectedGroup)}-${toProviderName(input.selectedPlan)}`,
    api_type: input.apiType,
    base_url: input.baseUrl,
    upstream_path: input.upstreamPath || undefined,
    api_key: input.apiKey,
    models: input.models.map((m) => ({
      name: m.name,
      context_window: m.contextWindow,
      patches: m.patches.length > 0 ? m.patches : undefined,
      stream_timeout_ms: m.stream_timeout_ms ?? undefined,
      capabilities:
        m.capabilities && m.capabilities.length > 0
          ? m.capabilities
          : undefined,
    })),
    concurrency_mode: input.concurrencyMode,
    max_concurrency:
      input.concurrencyMode !== "none" ? input.maxConcurrency : undefined,
    queue_timeout_ms:
      input.concurrencyMode !== "none" ? input.queueTimeoutMs : undefined,
    max_queue_size:
      input.concurrencyMode !== "none" ? input.maxQueueSize : undefined,
  };
}

/** Build mapping entries by merging existing DB mappings with client defaults */
function buildMappingEntries(
  clientType: ClientType,
  enabledModels: ModelConfig[],
  existingMappings: MappingGroup[],
): MappingEntry[] {
  let clientModelNames: string[];
  if (clientType === "pi") {
    clientModelNames = enabledModels.map((m) => m.name);
  } else {
    clientModelNames =
      DEFAULT_CLIENT_MAPPINGS[clientType] ?? enabledModels.map((m) => m.name);
  }

  return clientModelNames.map((cmName) => {
    const existingGroup = existingMappings.find(
      (g) => g.client_model === cmName,
    );
    if (existingGroup) {
      let rule: Rule = {};
      try {
        rule = JSON.parse(existingGroup.rule);
      } catch {
        rule = {};
      }
      const targets = rule.targets ?? [];
      return {
        clientModel: cmName,
        targets:
          targets.length > 0
            ? targets.map((t) => ({
              backend_model: t.backend_model,
              provider_id: t.provider_id,
              overflow_provider_id: t.overflow_provider_id,
              overflow_model: t.overflow_model,
            }))
            : [
              {
                backend_model: enabledModels[0]?.name ?? "",
                provider_id: "__new__",
              },
            ],
        existing: true,
        existingId: existingGroup.id,
        tag: "existing" as const,
        active: !!existingGroup.is_active,
        originalActive: !!existingGroup.is_active,
      };
    }

    const defaultTarget =
      enabledModels[clientModelNames.indexOf(cmName)]?.name ??
      enabledModels[enabledModels.length - 1]?.name ??
      "";
    return {
      clientModel: cmName,
      targets: [{ backend_model: defaultTarget, provider_id: "__new__" }],
      existing: false,
      tag: (clientType === "pi" ? "auto" : "def") as "auto" | "def",
      active: true,
    };
  });
}

/** Resolve the effective apiType, preserving openai-responses for codex clients
 *  when the preset is openai-compatible. Anthropic presets are never overridden. */
function resolveApiType(
  clientFormat: string | undefined,
  presetApiType: string,
): "openai" | "openai-responses" | "anthropic" {
  if (
    clientFormat === "openai-responses" &&
    (presetApiType === "openai" || presetApiType === "openai-responses")
  ) {
    return "openai-responses";
  }
  return presetApiType as "openai" | "openai-responses" | "anthropic";
}

interface QuickSetupPayloadInput {
  isCustomProvider: boolean;
  selectedGroup: string;
  selectedPlan: string;
  apiType: "openai" | "openai-responses" | "anthropic";
  baseUrl: string;
  upstreamPath: string;
  apiKey: string;
  models: ModelConfig[];
  concurrencyMode: ConcurrencyMode;
  maxConcurrency: number;
  queueTimeoutMs: number;
  maxQueueSize: number;
  mappingEntries: MappingEntry[];
  recommendedRules: RecommendedRetryRule[];
  selectedRetryRules: Set<string>;
  transformRules: QuickSetupPayload["transform_rules"];
}

function buildQuickSetupPayload(
  input: QuickSetupPayloadInput,
): QuickSetupPayload {
  return {
    provider: buildProviderPayload({
      isCustom: input.isCustomProvider,
      selectedGroup: input.selectedGroup,
      selectedPlan: input.selectedPlan,
      apiType: input.apiType,
      baseUrl: input.baseUrl,
      upstreamPath: input.upstreamPath,
      apiKey: input.apiKey,
      models: input.models,
      concurrencyMode: input.concurrencyMode,
      maxConcurrency: input.maxConcurrency,
      queueTimeoutMs: input.queueTimeoutMs,
      maxQueueSize: input.maxQueueSize,
    }),
    mappings: input.mappingEntries
      .filter((m) => m.targets[0]?.backend_model)
      .map((m) => ({
        client_model: m.clientModel,
        backend_model: m.targets[0]?.backend_model ?? "",
      })),
    retry_rules: buildRetryRulesPayload(
      input.recommendedRules,
      input.selectedRetryRules,
    ),
    transform_rules: input.transformRules,
  };
}

function makeCurrentClient(
  clientType: Ref<ClientType>,
): ComputedRef<(typeof CLIENTS)[number] | undefined> {
  return computed(() => CLIENTS.find((c) => c.id === clientType.value));
}

function makeCurrentPreset(
  selectedGroup: Ref<string>,
  selectedPlan: Ref<string>,
  providerGroups: Ref<ProviderGroup[]>,
): ComputedRef<ProviderGroup["presets"][number] | undefined> {
  return computed(() => {
    if (!selectedGroup.value || !selectedPlan.value) return undefined;
    const group = providerGroups.value.find(
      (g) => g.group === selectedGroup.value,
    );
    if (!group) return undefined;
    return group.presets.find((p) => p.plan === selectedPlan.value);
  });
}

function makeBaseUrl(
  isCustomProvider: Ref<boolean>,
  customBaseUrl: Ref<string>,
  currentPreset: ComputedRef<ProviderGroup["presets"][number] | undefined>,
): ComputedRef<string> {
  return computed(() =>
    isCustomProvider.value
      ? customBaseUrl.value
      : (currentPreset.value?.baseUrl ?? ""),
  );
}

function makeUpstreamPath(
  isCustomProvider: Ref<boolean>,
  customUpstreamPath: Ref<string>,
  currentPreset: ComputedRef<ProviderGroup["presets"][number] | undefined>,
): ComputedRef<string> {
  return computed(() => {
    if (isCustomProvider.value) return customUpstreamPath.value;
    const preset = currentPreset.value;
    if (!preset) return "";
    const defaultPath =
      preset.apiType === "anthropic"
        ? "/v1/messages"
        : preset.apiType === "openai-responses"
          ? "/v1/responses"
          : "/v1/chat/completions";
    if (preset.upstreamPath && preset.upstreamPath !== defaultPath)
      return preset.upstreamPath;
    return "";
  });
}

function makeAvailablePlans(
  selectedGroup: Ref<string>,
  providerGroups: Ref<ProviderGroup[]>,
): ComputedRef<ProviderGroup["presets"]> {
  return computed(() => {
    const group = providerGroups.value.find(
      (g) => g.group === selectedGroup.value,
    );
    return group?.presets ?? [];
  });
}

function makeIsNonOpenaiEndpoint(
  baseUrl: ComputedRef<string>,
): ComputedRef<boolean> {
  return computed(() => !baseUrl.value.includes("openai.com"));
}

function makeRecommendedRules(
  selectedGroup: Ref<string>,
  allRecommendedRules: Ref<RecommendedRetryRule[]>,
): ComputedRef<RecommendedRetryRule[]> {
  return computed(() => {
    const group = selectedGroup.value;
    return allRecommendedRules.value.filter((r) => {
      if (!r.providers || r.providers.length === 0) return true;
      return r.providers.includes(group);
    });
  });
}

function computeProviderGroupDisplayInfo(
  isCustomProvider: ComputedRef<boolean>,
  selectedGroup: Ref<string>,
  selectedPlan: Ref<string>,
  modelConfigs: Ref<ModelConfig[]>,
  allProviders: Ref<ApiProvider[]>,
  t: (key: string, params?: Record<string, unknown>) => string,
): {
  currentProviderGroup: ComputedRef<{
    provider: { id: string; name: string };
    models: { name: string; contextWindow: number }[];
    isNew: boolean;
  } | null>;
  allProviderGroups: ComputedRef<
    {
      provider: { id: string; name: string };
      models: { name: string; contextWindow: number }[];
    }[]
  >;
} {
  const currentProviderGroup = computed(() => {
    if (!selectedGroup.value) return null;
    const tempId = isCustomProvider.value
      ? "__new_custom__"
      : `__new_${toProviderName(selectedGroup.value)}_${toProviderName(selectedPlan.value)}__`;
    const displayName = isCustomProvider.value
      ? t("quickSetup.provider.customProvider")
      : `${selectedGroup.value} - ${selectedPlan.value}`;
    return {
      provider: { id: tempId, name: displayName },
      models: modelConfigs.value
        .filter((m) => m.enabled)
        .map((m) => ({
          name: m.name,
          contextWindow: m.contextWindow,
        })),
      isNew: true,
    };
  });

  const allProviderGroups = computed(() => {
    const existing = allProviders.value.map((p) => ({
      provider: { id: p.id, name: p.name },
      models: (p.models ?? []).map((m) => ({
        name: m.name,
        contextWindow: m.context_window ?? DEFAULT_CONTEXT_WINDOW,
      })),
    }));
    if (
      currentProviderGroup.value &&
      currentProviderGroup.value.models.length > 0
    ) {
      return [...existing, currentProviderGroup.value];
    }
    return existing;
  });

  return { currentProviderGroup, allProviderGroups };
}

function applyPresetModels(
  preset: {
    models: string[];
    modelCapabilities?: Record<string, string[]>;
    apiType: "openai" | "openai-responses" | "anthropic";
  },
  modelConfigs: Ref<ModelConfig[]>,
  isNonOpenaiEndpoint: Ref<boolean>,
): void {
  modelConfigs.value = preset.models.map((name) => ({
    name,
    contextWindow: getDefaultContextWindow(name),
    enabled: true,
    patches: computeDefaultPatches(
      name,
      preset.apiType,
      isNonOpenaiEndpoint.value,
    ),
    stream_timeout_ms: DEFAULT_STREAM_TIMEOUT_MS,
    capabilities: preset.modelCapabilities?.[name],
  }));
}

function pushCustomModel(
  modelConfigs: Ref<ModelConfig[]>,
  name: string,
  apiType: "openai" | "openai-responses" | "anthropic",
  isNonOpenaiEndpoint: Ref<boolean>,
  contextWindow = DEFAULT_CONTEXT_WINDOW,
): void {
  modelConfigs.value.push({
    name,
    contextWindow,
    enabled: true,
    patches: computeDefaultPatches(name, apiType, isNonOpenaiEndpoint.value),
    stream_timeout_ms: DEFAULT_STREAM_TIMEOUT_MS,
    capabilities: ["text"],
  });
}

async function fetchQuickSetupInitialData(
  providerGroups: Ref<ProviderGroup[]>,
  allRecommendedRules: Ref<RecommendedRetryRule[]>,
  existingMappings: Ref<MappingGroup[]>,
  allProviders: Ref<ApiProvider[]>,
  selectClient: (type: ClientType) => void,
  toastError: (msg: string) => void,
): Promise<void> {
  try {
    const [groupsResult, rulesResult, mappingsResult, providersResult] =
      await Promise.allSettled([
        api.recommended.getProviders(),
        api.recommended.getRetryRules(),
        api.getMappingGroups(),
        api.getProviders(),
      ]);
    if (groupsResult.status === "fulfilled")
      providerGroups.value = groupsResult.value;
    if (rulesResult.status === "fulfilled")
      allRecommendedRules.value = rulesResult.value;
    if (mappingsResult.status === "fulfilled")
      existingMappings.value = mappingsResult.value as MappingGroup[];
    if (providersResult.status === "fulfilled")
      allProviders.value = providersResult.value as ApiProvider[];

    selectClient("claude-code");
  } catch (e: unknown) {
    console.error("quickSetup.load:", e);
    toastError(getApiMessage(e, ""));
  }
}

async function testQuickSetupConnection(
  apiKey: Ref<string>,
  connectionStatus: Ref<"idle" | "testing" | "ok" | "error">,
  toastErrorFn: (msg: string) => void,
): Promise<void> {
  if (!apiKey.value.trim()) {
    connectionStatus.value = "error";
    toastErrorFn("quickSetup.messages.fillApiKeyFirst");
    return;
  }
  connectionStatus.value = "testing";
  await new Promise((resolve) => setTimeout(resolve, CONNECTION_TEST_DELAY_MS));
  connectionStatus.value = "ok";
}

export function useQuickSetup() {
  const { t } = useI18n();

  const clientType = ref<ClientType>("claude-code");
  const providerGroups = ref<ProviderGroup[]>([]);
  const selectedGroup = ref("");
  const selectedPlan = ref("");
  const apiType = ref<"openai" | "openai-responses" | "anthropic">("anthropic");
  const apiKey = ref("");
  const modelConfigs = ref<ModelConfig[]>([]);
  const mappingEntries = ref<MappingEntry[]>([]);
  const allRecommendedRules = ref<RecommendedRetryRule[]>([]);
  const selectedRetryRules = ref<Set<string>>(new Set());
  const saving = ref(false);
  const connectionStatus = ref<"idle" | "testing" | "ok" | "error">("idle");
  const concurrencyMode = ref<ConcurrencyMode>("auto");
  const maxConcurrency = ref(DEFAULT_CONCURRENCY);
  const queueTimeoutMs = ref(DEFAULT_QUEUE_TIMEOUT_MS);
  const maxQueueSize = ref(DEFAULT_QUEUE_SIZE);
  const transformInjectHeaders = ref("");
  const transformDropFields = ref("");
  const transformRequestDefaults = ref("");
  const existingMappings = ref<MappingGroup[]>([]);
  const allProviders = ref<ApiProvider[]>([]);

  const isCustomProvider = computed(() => selectedGroup.value === "__custom__");
  const currentClient = makeCurrentClient(clientType);
  const currentPreset = makeCurrentPreset(
    selectedGroup,
    selectedPlan,
    providerGroups,
  );
  const customBaseUrl = ref("");
  const customUpstreamPath = ref("");
  const baseUrl = makeBaseUrl(isCustomProvider, customBaseUrl, currentPreset);
  const upstreamPath = makeUpstreamPath(
    isCustomProvider,
    customUpstreamPath,
    currentPreset,
  );
  const availablePlans = makeAvailablePlans(selectedGroup, providerGroups);
  const isNonOpenaiEndpoint = makeIsNonOpenaiEndpoint(baseUrl);
  const recommendedRules = makeRecommendedRules(
    selectedGroup,
    allRecommendedRules,
  );
  const providerGroupInfo = computeProviderGroupDisplayInfo(
    isCustomProvider,
    selectedGroup,
    selectedPlan,
    modelConfigs,
    allProviders,
    t,
  );
  const allProviderGroups = providerGroupInfo.allProviderGroups;

  function updateMappings() {
    const enabledModels = modelConfigs.value.filter((m) => m.enabled);
    mappingEntries.value = buildMappingEntries(
      clientType.value,
      enabledModels,
      existingMappings.value,
    );
  }

  function autoSelectRetryRules() {
    selectedRetryRules.value = new Set(
      recommendedRules.value.filter((r) => !r.exists).map((r) => r.name),
    );
  }

  function selectClient(type: ClientType) {
    clientType.value = type;
    updateMappings();
  }

  function onProviderChange(group: string) {
    selectedGroup.value = group;
    selectedPlan.value = "";
    modelConfigs.value = [];
    if (group === "__custom__") {
      apiType.value = "openai";
      customBaseUrl.value = "";
      customUpstreamPath.value = "";
    } else {
      const groupData = providerGroups.value.find((g) => g.group === group);
      if (groupData && groupData.presets.length > 0) {
        const client = currentClient.value;
        const compatibleFormats =
          client?.format === "openai-responses"
            ? ["openai-responses", "openai"]
            : client
              ? [client.format]
              : [];
        const match = client
          ? groupData.presets.find((p) => compatibleFormats.includes(p.apiType))
          : null;
        const preset = match ?? groupData.presets[0];
        selectedPlan.value = preset.plan;
        apiType.value = resolveApiType(client?.format, preset.apiType);
        applyPresetModels(preset, modelConfigs, isNonOpenaiEndpoint);
      }
    }
    updateMappings();
    autoSelectRetryRules();
  }

  function onPlanChange(plan: string) {
    selectedPlan.value = plan;
    const group = providerGroups.value.find(
      (g) => g.group === selectedGroup.value,
    );
    if (!group) return;
    const preset = group.presets.find((p) => p.plan === plan);
    if (!preset) return;
    apiType.value = resolveApiType(currentClient.value?.format, preset.apiType);
    applyPresetModels(preset, modelConfigs, isNonOpenaiEndpoint);
    updateMappings();
  }

  watch(apiType, () => {
    for (const model of modelConfigs.value) {
      model.patches = computeDefaultPatches(
        model.name,
        apiType.value,
        isNonOpenaiEndpoint.value,
      );
    }
  });

  function toggleRetryRule(name: string, checked: boolean) {
    const next = new Set(selectedRetryRules.value);
    if (checked) next.add(name);
    else next.delete(name);
    selectedRetryRules.value = next;
  }

  function updateMappingTargets(index: number, targets: MappingTarget[]) {
    const next = [...mappingEntries.value];
    next[index] = { ...next[index], targets };
    mappingEntries.value = next;
  }

  function toggleMappingActive(index: number) {
    const next = [...mappingEntries.value];
    next[index] = { ...next[index], active: !next[index].active };
    mappingEntries.value = next;
  }

  function addMappingEntry(clientModel: string, targetModel: string) {
    const existing = mappingEntries.value.filter(
      (m) => m.clientModel !== clientModel,
    );
    existing.push({
      clientModel,
      targets: [{ backend_model: targetModel, provider_id: "__new__" }],
      existing: false,
      tag: "cust" as const,
      active: true,
    });
    mappingEntries.value = existing;
  }

  function removeMappingEntry(clientModel: string) {
    const entry = mappingEntries.value.find(
      (m) => m.clientModel === clientModel,
    );
    if (entry?.existing) {
      toast.error(t("quickSetup.messages.existingMappingDelete"));
      return;
    }
    mappingEntries.value = mappingEntries.value.filter(
      (m) => m.clientModel !== clientModel,
    );
  }

  function onConcurrencyModeChange(mode: ConcurrencyMode) {
    concurrencyMode.value = mode;
    if (mode === "auto") maxConcurrency.value = DEFAULT_CONCURRENCY;
    else if (mode === "manual") maxConcurrency.value = 3;
  }

  async function testConnection() {
    return testQuickSetupConnection(apiKey, connectionStatus, (msg) =>
      toast.error(t(msg)),
    );
  }

  function addCustomModel(
    name: string,
    contextWindow = DEFAULT_CONTEXT_WINDOW,
  ) {
    pushCustomModel(
      modelConfigs,
      name,
      apiType.value,
      isNonOpenaiEndpoint,
      contextWindow,
    );
  }

  async function submit() {
    if (!currentPreset.value) {
      toast.error(t("quickSetup.messages.selectProviderAndPlan"));
      return;
    }
    if (!apiKey.value.trim()) {
      toast.error(t("quickSetup.messages.fillApiKey"));
      return;
    }
    saving.value = true;
    try {
      const transformRules = parseTransformRules(
        transformInjectHeaders.value.trim(),
        transformDropFields.value.trim(),
        transformRequestDefaults.value.trim(),
        (key) => toast.error(t(`quickSetup.messages.${key}`)),
      );
      if (transformRules === false) return;
      const payload = buildQuickSetupPayload({
        isCustomProvider: isCustomProvider.value,
        selectedGroup: selectedGroup.value,
        selectedPlan: selectedPlan.value,
        apiType: apiType.value,
        baseUrl: baseUrl.value,
        upstreamPath: upstreamPath.value,
        apiKey: apiKey.value.trim(),
        models: modelConfigs.value,
        concurrencyMode: concurrencyMode.value,
        maxConcurrency: maxConcurrency.value,
        queueTimeoutMs: queueTimeoutMs.value,
        maxQueueSize: maxQueueSize.value,
        mappingEntries: mappingEntries.value,
        recommendedRules: recommendedRules.value,
        selectedRetryRules: selectedRetryRules.value,
        transformRules: transformRules,
      });
      await api.quickSetup(payload);
      const toggleErrors = await toggleChangedMappings(mappingEntries.value);
      if (toggleErrors.length > 0) {
        toast.success(
          t("quickSetup.messages.setupCompleteWithErrors", {
            count: toggleErrors.length,
          }),
        );
      } else {
        toast.success(t("quickSetup.messages.setupComplete"));
      }
      await new Promise((r) => setTimeout(r, POST_SAVE_REDIRECT_MS));
      router.push("/");
    } catch (e: unknown) {
      console.error("quickSetup.save:", e);
      toast.error(getApiMessage(e, t("quickSetup.messages.setupFailed")));
    } finally {
      saving.value = false;
    }
  }

  onMounted(() => {
    fetchQuickSetupInitialData(
      providerGroups,
      allRecommendedRules,
      existingMappings,
      allProviders,
      selectClient,
      (msg) => toast.error(msg),
    );
  });

  return {
    clientType,
    providerGroups,
    selectedGroup,
    selectedPlan,
    apiType,
    apiKey,
    modelConfigs,
    mappingEntries,
    allRecommendedRules,
    recommendedRules,
    selectedRetryRules,
    saving,
    connectionStatus,
    currentClient,
    currentPreset,
    baseUrl,
    customBaseUrl,
    upstreamPath,
    customUpstreamPath,
    isCustomProvider,
    availablePlans,
    isNonOpenaiEndpoint,
    concurrencyMode,
    maxConcurrency,
    queueTimeoutMs,
    maxQueueSize,
    transformInjectHeaders,
    transformDropFields,
    transformRequestDefaults,
    existingMappings,
    allProviders,
    allProviderGroups,
    selectClient,
    onProviderChange,
    onPlanChange,
    updateMappings,
    updateMappingTargets,
    toggleMappingActive,
    addMappingEntry,
    removeMappingEntry,
    toggleRetryRule,
    onConcurrencyModeChange,
    testConnection,
    submit,
    addCustomModel,
  };
}

import type { ActiveRequest } from "@/types/monitor";
import type { LogEntry } from "@/components/logs/types";
import { extractThinkingLevel } from "@/utils/thinking-level";

export type DataSource = "realtime" | "history";

export const MS_PER_SECOND = 1000;
export const HTTP_ERROR_THRESHOLD = 400;

export interface UnifiedRequestOverview {
  id: string;
  model: string;
  backendModel: string | null;
  originalModel: string | null;
  statusCode: number | null;
  isStream: boolean;
  apiType: "openai" | "anthropic";
  providerName: string | null;
  clientIp: string | undefined;
  sessionId: string | null;
  latencyMs: number | null;
  ttftMs: number | null;
  inputTokens: number | null;
  outputTokens: number | null;
  tokensPerSecond: number | null;
  cacheReadTokens: number | null;
  cacheWriteTokens: number | null;
  stopReason: string | null;
  isComplete: boolean;
  attempts: {
    statusCode: number | null;
    error: string | null;
    latencyMs: number;
    providerId: string;
  }[];
  status: "pending" | "completed" | "failed";
  clientRequest: string | null;
  upstreamRequest: string | null;
  responseBody: string | null;
  upstreamResponse: string | null;
  errorMessage: string | null;
  createdAt: string | null;
  inputTokensEstimated: boolean;
  clientType: string | null;
  cacheReadTokensEstimated: number | null;
  mappingReason?: string;
  thinkingLevel: string;
}

export function fromActiveRequest(
  req: ActiveRequest,
  nonStreamBody?: string | null,
): UnifiedRequestOverview {
  const lastAttempt =
    req.attempts.length > 0 ? req.attempts[req.attempts.length - 1] : undefined;
  const m = req.streamMetrics;

  let tokensPerSecond = m?.tokensPerSecond ?? null;
  if (!tokensPerSecond && m && m.outputTokens && m.ttftMs && req.completedAt) {
    const outputTime =
      (req.completedAt - req.startTime - m.ttftMs) / MS_PER_SECOND;
    if (outputTime > 0) tokensPerSecond = m.outputTokens / outputTime;
  }

  return {
    id: req.id,
    model: req.model,
    backendModel: null,
    originalModel: null,
    statusCode:
      req.status === "completed" ? (lastAttempt?.statusCode ?? null) : null,
    isStream: req.isStream,
    apiType: req.apiType,
    providerName: req.providerName,
    clientIp: req.clientIp,
    sessionId: req.sessionId ?? null,
    latencyMs: req.completedAt ? req.completedAt - req.startTime : null,
    ttftMs: m?.ttftMs ?? null,
    inputTokens: m?.inputTokens ?? null,
    outputTokens: m?.outputTokens ?? null,
    tokensPerSecond,
    cacheReadTokens: m?.cacheReadTokens ?? null,
    cacheWriteTokens: null,
    stopReason: m?.stopReason ?? null,
    isComplete: m?.isComplete ?? false,
    attempts: req.attempts.map((a) => ({
      statusCode: a.statusCode,
      error: a.error,
      latencyMs: a.latencyMs,
      providerId: a.providerId,
    })),
    status: req.status,
    clientRequest: req.clientRequest ?? null,
    upstreamRequest: req.upstreamRequest ?? null,
    responseBody: nonStreamBody ?? null,
    upstreamResponse: null,
    errorMessage: null,
    createdAt: null,
    inputTokensEstimated: false,
    clientType: null,
    cacheReadTokensEstimated: m?.cacheReadTokensEstimated ?? null,
    mappingReason: req.mappingReason,
    thinkingLevel: req.thinkingLevel ?? "off",
  };
}

/**
 * 从日志字段提取实际的响应 body。
 * upstream_response 可能只是 {"statusCode":200, "body":null} 形式的 headers 元数据，
 * 需要检测 body 字段是否存在真实内容。
 */
function extractResponseBody(upstreamResponse: string | null): string | null {
  if (!upstreamResponse) return null;
  try {
    const parsed = JSON.parse(upstreamResponse);
    // headers 元数据包装格式：{ statusCode, headers, body }
    if (
      typeof parsed.statusCode === "number" &&
      parsed.headers &&
      !parsed.content &&
      !parsed.choices
    ) {
      return typeof parsed.body === "string" ? parsed.body : null;
    }
    return upstreamResponse;
  } catch {
    return upstreamResponse;
  }
}

/** Router 内部错误前缀，这些是 early error detection 等机制生成的诊断标签，不应对用户展示 */
const ROUTER_INTERNAL_ERROR_PREFIXES = [
  "stream_error: upstream returned 200 but body contains error",
];

// 注意：此函数与 router/src/utils/mapping-reason-parser.ts 保持同步
// 修改此函数时必须同步修改 router 端并确保测试通过
const KNOWN_MAPPING_REASONS = new Set([
  "direct_format",
  "group_base_rule",
  "group_schedule",
  "fallback_provider",
  "overflow_redirect",
  "failover_retry",
]);

/**
 * 从 pipeline_snapshot JSON 中提取映射原因。
 * 优先检查 overflow stage（triggered === true → "overflow_redirect"），
 * 否则取 routing stage 的 mapping_reason 字段。
 * 只返回白名单中的值，避免未知的 mapping_reason 导致 i18n key 断裂。
 */
export function parseMappingReason(
  snapshot: string | null | undefined,
): string | undefined {
  if (!snapshot) return undefined;
  try {
    const parsed: unknown = JSON.parse(snapshot);
    const stages: Array<Record<string, unknown>> = Array.isArray(parsed)
      ? parsed
      : [];
    if (stages.length === 0) return undefined;
    // 优先检查 overflow stage
    for (const stage of stages) {
      if (stage.stage === "overflow" && stage.triggered === true) {
        return "overflow_redirect";
      }
    }
    // 取 routing stage 的 mapping_reason
    for (const stage of stages) {
      if (
        stage.stage === "routing" &&
        typeof stage.mapping_reason === "string"
      ) {
        return KNOWN_MAPPING_REASONS.has(stage.mapping_reason)
          ? stage.mapping_reason
          : undefined;
      }
    }
    return undefined;
  } catch {
    return undefined;
  }
}

function isRouterInternalError(msg: string | null | undefined): boolean {
  if (!msg) return false;
  return ROUTER_INTERNAL_ERROR_PREFIXES.some((prefix) =>
    msg.startsWith(prefix),
  );
}

export function fromLogEntry(entry: LogEntry): UnifiedRequestOverview {
  const inputTokens = entry.input_tokens ?? null;
  const outputTokens = entry.output_tokens ?? null;
  const ttftMs = entry.ttft_ms ?? null;

  let tokensPerSecond = entry.tokens_per_second ?? null;
  if (!tokensPerSecond && outputTokens && ttftMs && entry.latency_ms) {
    const outputTime = (entry.latency_ms - ttftMs) / MS_PER_SECOND;
    if (outputTime > 0) tokensPerSecond = outputTokens / outputTime;
  }

  // 非流式：从 upstream_response.body 提取完整 JSON 响应
  // 流式：upstream_response.body 为 null，回退到 stream_text_content（纯文本）
  const responseBody =
    extractResponseBody(entry.upstream_response) ??
    entry.stream_text_content ??
    null;

  return {
    id: entry.id,
    model: entry.original_model ?? entry.model ?? "unknown",
    backendModel: entry.backend_model,
    originalModel: entry.original_model,
    statusCode: entry.status_code,
    isStream: !!entry.is_stream,
    apiType:
      entry.api_type === "openai" || entry.api_type === "anthropic"
        ? entry.api_type
        : "openai",
    providerName: entry.provider_name,
    clientIp: undefined,
    sessionId: entry.session_id ?? null,
    latencyMs: entry.latency_ms,
    ttftMs,
    inputTokens,
    outputTokens,
    tokensPerSecond,
    cacheReadTokens: entry.cache_read_tokens ?? null,
    cacheWriteTokens: null,
    stopReason: entry.stop_reason ?? null,
    isComplete: !!entry.metrics_complete,
    attempts: [],
    status:
      (entry.status_code ?? 0) >= HTTP_ERROR_THRESHOLD ? "failed" : "completed",
    clientRequest: entry.client_request,
    upstreamRequest: entry.upstream_request,
    responseBody,
    upstreamResponse: entry.upstream_response,
    errorMessage: isRouterInternalError(entry.error_message)
      ? null
      : entry.error_message,
    createdAt: entry.created_at,
    inputTokensEstimated: entry.input_tokens_estimated === 1,
    clientType: entry.client_type ?? null,
    cacheReadTokensEstimated: entry.cache_read_tokens_estimated ?? null,
    mappingReason: parseMappingReason(entry.pipeline_snapshot),
    thinkingLevel:
      entry.thinking_level ??
      extractThinkingLevel(entry.client_request, entry.api_type),
  };
}

